-- sinkronkan stok tersedia dengan peminjaman aktif
UPDATE b SET Tersedia = b.StokTotal - ISNULL((SELECT COUNT(*) FROM dbo.Peminjaman p WHERE p.BukuId = b.BukuId AND p.Status = N'Dipinjam'), 0)
FROM dbo.Buku b;
GO

